def floorCeilIndices(nums, x):
    n = len(nums)

    def first_true(pred):
        lo, hi = 0, n
        while lo < hi:
            mid = (lo + hi) // 2
            if pred(nums[mid]):
                hi = mid
            else:
                lo = mid + 1
        return lo

    ceil_i = first_true(lambda v: v >= x)
    upper = first_true(lambda v: v > x)
    return [upper - 1, ceil_i if ceil_i < n else -1]
